{
  "name": "QuTech CC 中央控制器",
  "name_en": "QuTech Central Controller (CC)",
  "manufacturer": "QuTech",
  "description": "一台机架式实验控制硬件，包含用于实时执行脉冲序列的 sequencer(s) 与与多个 CCIO（数字 I/O）通道。支持上传/汇编序列程序、启动/停止 sequencer、校准数字 I/O、设置 VSM（矢量切换矩阵）延时并读取调试寄存器与跟踪数据。主要用于超导量子比特等实验中对时序脉冲和数字信号的精确定时与协调。",
  "description_en": "A rack-mounted laboratory control instrument providing real-time sequencers and multiple CCIO digital I/O channels. It accepts uploaded sequence programs (assembly), can start/stop sequencers, calibrate digital I/O lines, set VSM delay values, and read debug registers and traces. Used to generate and coordinate timed pulse sequences and digital signals in quantum experiments (e.g., superconducting qubit control).",
  "actions": [
    {
      "action_name": "auto-assemble",
      "description": "将给定的序列程序字符串进行汇编/准备，生成可在 CC 上运行的序列代码（上传前的组装步骤）。",
      "description_en": "Assemble the provided sequence program string into sequencer code prepared for the CC (preparation step before upload)."
    },
    {
      "action_name": "auto-assemble_and_start",
      "description": "汇编序列程序并在 CC 上启动 sequencer，立即开始执行该程序。",
      "description_en": "Assemble the sequence program and start the sequencer on the CC to begin execution immediately."
    },
    {
      "action_name": "auto-calibrate_dio",
      "description": "对指定 CCIO 的数字 I/O 线执行校准流程（比对预期位模式以确定时序/阈值等）。",
      "description_en": "Run a calibration routine on the specified CCIO digital I/O lines (compare against expected bit patterns to determine timing/margin)."
    },
    {
      "action_name": "auto-debug_get_ccio_reg",
      "description": "读取指定 CCIO 的调试寄存器内容（仅用于诊断/验证硬件寄存器值）。",
      "description_en": "Read a debug register from the specified CCIO (for diagnostic/verification of hardware register values)."
    },
    {
      "action_name": "auto-debug_get_ccio_trace",
      "description": "获取指定 CCIO 的跟踪数据（调试用，返回采样或事件记录）。",
      "description_en": "Retrieve trace data from the specified CCIO (debugging; returns sampled/event trace records)."
    },
    {
      "action_name": "auto-debug_get_traces",
      "description": "根据提供的 CCIO 掩码批量获取跟踪数据，用于调试多个 CCIO 通道。",
      "description_en": "Fetch traces in bulk for multiple CCIOs according to the provided CCIO mask, for multi-channel debugging."
    },
    {
      "action_name": "auto-debug_marker_in",
      "description": "在指定 CCIO 的某个数字位上设置（激活）调试 marker 信号（用于触发/对齐诊断）。",
      "description_en": "Set/activate a debug marker signal on a specified digital bit of the CCIO (used for triggering/alignment diagnostics)."
    },
    {
      "action_name": "auto-debug_marker_off",
      "description": "关闭指定 CCIO 的调试 marker（停用先前激活的调试标记）。",
      "description_en": "Turn off the debug marker on the specified CCIO (deactivate a previously set debug marker)."
    },
    {
      "action_name": "auto-debug_marker_out",
      "description": "在指定 CCIO 的某个数字位上输出（拉高/拉低）调试 marker 信号以供外部测量或触发使用。",
      "description_en": "Output a debug marker signal on a specified digital bit of the CCIO (drive marker high/low for external measurement or triggering)."
    },
    {
      "action_name": "auto-debug_set_ccio_trace_on",
      "description": "在指定 CCIO 上启用跟踪通道（将某个跟踪索引切换为在线以采集调试数据）。",
      "description_en": "Enable a trace channel on the specified CCIO (switch a trace index on to collect debug data)."
    },
    {
      "action_name": "auto-print_status_operation",
      "description": "打印并显示 CC 的运行/操作状态汇总（结合 CCCORE 与 CCIO 的运行信息）。",
      "description_en": "Print and display an aggregated operation/run status of the CC (combines CCCORE and CCIO runtime information)."
    },
    {
      "action_name": "auto-print_status_questionable",
      "description": "打印并显示 CC 的“questionable”状态汇总（警告/异常相关的条件信息）。",
      "description_en": "Print and show the CC's 'questionable' status summary (conditions related to warnings/anomalies)."
    },
    {
      "action_name": "auto-sequence_program_assemble",
      "description": "define 上传到 CC 的序列程序字符串（定义设备上存储的序列程序内容）。",
      "description_en": "define the sequence program string uploaded to the CC (defines the sequence program stored on the device)."
    },
    {
      "action_name": "auto-set_q1_reg",
      "description": "set 在 CC/CCIO 上的 q1 寄存器的值（仅在 CC 停止时允许修改）。",
      "description_en": "set the q1 register value on the CC/CCIO (allowed only when the CC is stopped)."
    },
    {
      "action_name": "auto-set_seqbar_cnt",
      "description": "设置序列屏障/计数器值（修改 sequencer 的某个计数或屏障计数，无需停止 CC）。",
      "description_en": "Set the sequence barrier/counter value (modify a sequencer counter/barrier; does not require stopping the CC)."
    },
    {
      "action_name": "auto-set_status_operation_run_enable",
      "description": "set 启用或禁用 operation-run 状态上报（控制是否报告运行状态）。",
      "description_en": "set whether operation-run status reporting is enabled (controls reporting of run state)."
    },
    {
      "action_name": "auto-set_status_questionable_bplink_enable",
      "description": "set 启用或禁用 bplink 相关的 questionable 状态上报。",
      "description_en": "set whether bplink-related questionable status reporting is enabled."
    },
    {
      "action_name": "auto-set_status_questionable_config_enable",
      "description": "set 启用或禁用配置相关的 questionable 状态上报。",
      "description_en": "set whether configuration-related questionable status reporting is enabled."
    },
    {
      "action_name": "auto-set_status_questionable_frequency_enable",
      "description": "set 启用或禁用频率相关的 questionable 状态上报。",
      "description_en": "set whether frequency-related questionable status reporting is enabled."
    },
    {
      "action_name": "auto-set_status_questionable_instrument_enable",
      "description": "set 启用或禁用仪器级别的 questionable 状态上报。",
      "description_en": "set whether instrument-level questionable status reporting is enabled."
    },
    {
      "action_name": "auto-set_status_questionable_instrument_idetail_bplink_enable",
      "description": "set 启用或禁用仪器详细信息中 bplink 的 questionable 状态上报。",
      "description_en": "set whether bplink questionable status reporting is enabled in instrument detailed info."
    },
    {
      "action_name": "auto-set_status_questionable_instrument_idetail_config_enable",
      "description": "set 启用或禁用仪器详细信息中配置项的 questionable 状态上报。",
      "description_en": "set whether configuration questionable status reporting is enabled in instrument detailed info."
    },
    {
      "action_name": "auto-set_status_questionable_instrument_idetail_diocal_enable",
      "description": "set 启用或禁用仪器详细信息中数字 I/O 校准（diocal）的 questionable 状态上报。",
      "description_en": "set whether digital I/O calibration (diocal) questionable status reporting is enabled in instrument detailed info."
    },
    {
      "action_name": "auto-set_status_questionable_instrument_idetail_freq_enable",
      "description": "set 启用或禁用仪器详细信息中频率项的 questionable 状态上报。",
      "description_en": "set whether frequency questionable status reporting is enabled in instrument detailed info."
    },
    {
      "action_name": "auto-set_status_questionable_instrument_isummary_enable",
      "description": "set 启用或禁用仪器摘要级别的 questionable 状态上报。",
      "description_en": "set whether instrument-summary-level questionable status reporting is enabled."
    },
    {
      "action_name": "auto-set_vsm_delay_fall",
      "description": "set 在指定 CCIO 的某个数字位上 VSM 的下降边延迟（以 833 ps 步长计）。",
      "description_en": "set the VSM fall-edge delay for a specified digital bit on the CCIO (in 833 ps steps)."
    },
    {
      "action_name": "auto-set_vsm_delay_rise",
      "description": "set 在指定 CCIO 的某个数字位上 VSM 的上升边延迟（以 833 ps 步长计）。",
      "description_en": "set the VSM rise-edge delay for a specified digital bit on the CCIO (in 833 ps steps)."
    },
    {
      "action_name": "auto-start",
      "description": "启动 CC 上的 sequencer（开始执行已加载的序列程序，可选择等待操作完成以确认已启动）。",
      "description_en": "Start the sequencer(s) on the CC (begin executing the loaded sequence program; optionally wait for operation-complete to confirm start)."
    },
    {
      "action_name": "auto-status_preset",
      "description": "执行状态预设：打开事件/状态上报并根据 SCPI 标准初始化/清除状态寄存器以准备运行。 ",
      "description_en": "Perform status preset: enable event/status reporting and initialize/clear status registers per SCPI, preparing the device for operation."
    },
    {
      "action_name": "auto-stop",
      "description": "停止 CC 上的 sequencer（终止当前序列执行，可选择等待操作完成以确认停止）。",
      "description_en": "Stop the sequencer(s) on the CC (terminate current sequence execution; optionally wait for operation-complete to confirm stop)."
    },
    {
      "action_name": "auto-get_sequence_program_assemble",
      "description": "get 下载/存储在设备上的序列程序字符串（获取当前上传的序列源码）。",
      "description_en": "get the sequence program string downloaded/stored on the device (retrieve the currently uploaded sequence source)."
    },
    {
      "action_name": "auto-get_assembler_success",
      "description": "get 查询最近一次汇编操作是否成功（汇编成功标志）。",
      "description_en": "get whether the most recent assembly operation succeeded (assembler success flag)."
    },
    {
      "action_name": "auto-get_assembler_log",
      "description": "get 检索最近一次汇编过程的日志或诊断信息（包含错误/警告信息）。",
      "description_en": "get the log or diagnostic output from the most recent assembly process (includes errors/warnings)."
    },
    {
      "action_name": "auto-get_q1_reg",
      "description": "get 读取 CC/CCIO 上的 q1 寄存器值（仅在 CC 停止时可读/有效）。",
      "description_en": "get the q1 register value on the CC/CCIO (readable/valid only when the CC is stopped)."
    },
    {
      "action_name": "auto-get_calibrate_dio_success",
      "description": "get 查询最近一次数字 I/O 校准是否成功。",
      "description_en": "get whether the most recent digital I/O calibration succeeded."
    },
    {
      "action_name": "auto-get_calibrate_dio_status",
      "description": "get 获取数字 I/O 校准的当前状态（详细步骤/进度或状态码）。",
      "description_en": "get the current status of the digital I/O calibration (detailed step/progress or status code)."
    },
    {
      "action_name": "auto-get_calibrate_dio_read_index",
      "description": "get 获取数字 I/O 校准过程中读取的索引或位置指示（用于诊断校准序列）。",
      "description_en": "get the read index or position indicator used during digital I/O calibration (for diagnosing the calibration sequence)."
    },
    {
      "action_name": "auto-get_calibrate_dio_margin",
      "description": "get 获取数字 I/O 校准结果的 margin（可用作时序/阈值裕度信息）。",
      "description_en": "get the calibration margin result for digital I/O (timing/threshold margin information)."
    },
    {
      "action_name": "auto-get_vsm_delay_rise",
      "description": "get 读取指定 CCIO 指定位的 VSM 上升边延迟值（以 833 ps 步长表示）。",
      "description_en": "get the VSM rise-edge delay value for a specified bit on the CCIO (expressed in 833 ps steps)."
    },
    {
      "action_name": "auto-get_vsm_delay_fall",
      "description": "get 读取指定 CCIO 指定位的 VSM 下降边延迟值（以 833 ps 步长表示）。",
      "description_en": "get the VSM fall-edge delay value for a specified bit on the CCIO (expressed in 833 ps steps)."
    },
    {
      "action_name": "auto-get_status_questionable_frequency",
      "description": "get 查询与频率相关的 questionable 状态位或掩码信息。",
      "description_en": "get the frequency-related questionable status bits or mask information."
    },
    {
      "action_name": "auto-get_status_questionable_frequency_enable",
      "description": "get 查询是否启用了频率相关的 questionable 状态上报。",
      "description_en": "get whether frequency-related questionable status reporting is enabled."
    },
    {
      "action_name": "auto-get_status_questionable_config",
      "description": "get 获取与配置相关的 questionable 状态信息（配置异常或警告）。",
      "description_en": "get questionable status information related to configuration (configuration anomalies or warnings)."
    },
    {
      "action_name": "auto-get_status_questionable_config_enable",
      "description": "get 查询是否启用了配置相关的 questionable 状态上报。",
      "description_en": "get whether configuration-related questionable status reporting is enabled."
    },
    {
      "action_name": "auto-get_status_questionable_bplink",
      "description": "get 获取与 bplink 相关的 questionable 状态信息（链路/通信异常）。",
      "description_en": "get questionable status information related to bplink (link/communication anomalies)."
    },
    {
      "action_name": "auto-get_status_questionable_bplink_enable",
      "description": "get 查询是否启用了 bplink 相关的 questionable 状态上报。",
      "description_en": "get whether bplink-related questionable status reporting is enabled."
    },
    {
      "action_name": "auto-get_status_operation_run",
      "description": "get 获取当前运行/操作状态（是否正在执行序列等运行标志）。",
      "description_en": "get the current operation/run status (whether sequences are executing, run flags, etc.)."
    },
    {
      "action_name": "auto-get_status_operation_run_enable",
      "description": "get 查询是否启用了 operation-run 状态上报。",
      "description_en": "get whether operation-run status reporting is enabled."
    },
    {
      "action_name": "auto-get_status_questionable_instrument",
      "description": "get 获取仪器级别的 questionable 状态信息（综合性警告/错误指标）。",
      "description_en": "get instrument-level questionable status information (composite warnings/errors indicators)."
    },
    {
      "action_name": "auto-get_status_questionable_instrument_enable",
      "description": "get 查询是否启用了仪器级别的 questionable 状态上报。",
      "description_en": "get whether instrument-level questionable status reporting is enabled."
    },
    {
      "action_name": "auto-get_status_questionable_instrument_isummary",
      "description": "get 获取仪器摘要级别的 questionable 状态汇总（各模块的概要状态）。",
      "description_en": "get a summary of instrument-summary-level questionable statuses (overview across modules)."
    },
    {
      "action_name": "auto-get_status_questionable_instrument_isummary_enable",
      "description": "get 查询是否启用了仪器摘要级别的 questionable 状态上报。",
      "description_en": "get whether instrument-summary-level questionable status reporting is enabled."
    },
    {
      "action_name": "auto-get_status_questionable_instrument_idetail_freq",
      "description": "get 获取仪器详细信息中与频率相关的 questionable 状态细节。",
      "description_en": "get detailed questionable status information related to frequency within instrument detailed info."
    },
    {
      "action_name": "auto-get_status_questionable_instrument_idetail_freq_enable",
      "description": "get 查询是否启用了仪器详细信息中频率项的 questionable 状态上报。",
      "description_en": "get whether frequency questionable status reporting is enabled in instrument detailed info."
    },
    {
      "action_name": "auto-get_status_questionable_instrument_idetail_config",
      "description": "get 获取仪器详细信息中与配置项相关的 questionable 状态细节。",
      "description_en": "get detailed questionable status information related to configuration within instrument detailed info."
    },
    {
      "action_name": "auto-get_status_questionable_instrument_idetail_config_enable",
      "description": "get 查询是否启用了仪器详细信息中配置项的 questionable 状态上报。",
      "description_en": "get whether configuration questionable status reporting is enabled in instrument detailed info."
    },
    {
      "action_name": "auto-get_status_questionable_instrument_idetail_bplink",
      "description": "get 获取仪器详细信息中与 bplink 相关的 questionable 状态细节。",
      "description_en": "get detailed questionable status information related to bplink within instrument detailed info."
    },
    {
      "action_name": "auto-get_status_questionable_instrument_idetail_bplink_enable",
      "description": "get 查询是否启用了仪器详细信息中 bplink 项的 questionable 状态上报。",
      "description_en": "get whether bplink questionable status reporting is enabled in instrument detailed info."
    },
    {
      "action_name": "auto-get_status_questionable_instrument_idetail_diocal",
      "description": "get 获取仪器详细信息中数字 I/O 校准（diocal）的 questionable 状态细节。",
      "description_en": "get detailed questionable status information for digital I/O calibration (diocal) within instrument detailed info."
    },
    {
      "action_name": "auto-get_status_questionable_instrument_idetail_diocal_enable",
      "description": "get 查询是否启用了仪器详细信息中数字 I/O 校准项的 questionable 状态上报。",
      "description_en": "get whether diocal questionable status reporting is enabled in instrument detailed info."
    }
  ],
  "tag_hints": [
    "qubit control",
    "sequencer",
    "pulse sequence assembly",
    "digital I/O calibration",
    "VSM delay (timing adjustment)",
    "instrument status monitoring",
    "debug trace/register read"
  ]
}
